from pathlib import Path
import json,html,hashlib,subprocess,re
out=Path(__file__).parent;root=out.parents[2]
load=lambda name:json.loads((out/name).read_text())
esc=lambda v:html.escape(str(v))
usage=load('usage-summary.json');tot=usage['totals'];orig=load('original-terminal.json');new=load('reviewed-terminal.json');manifest=load('manifest.json')
checks0=load('original-checks.json');checks1=load('reviewed-checks.json');metrics=load('code-metrics.json')
testlog=(out/'reviewed-tests.txt').read_text();testcount=re.search(r'(?:#|ℹ) tests (\d+)',testlog).group(1)
source=lambda path,label:f'<a href="{esc(path)}">{esc(label)}</a>'
evidence=lambda file,label:source('reports/tetris-003-review/'+file,label)
fmt=lambda n:f'{n:,}'
roles=''
for role,data in usage['roles'].items():
 roles+=f'<tr><th>{role.title()}</th><td>{data["callsStarted"]}</td><td>{fmt(data["input"])}</td><td>{fmt(data["cacheRead"])}</td><td>{fmt(data["output"])}</td><td>{fmt(data["totalTokens"])}</td><td>${data["reportedCostUSD"]:.6f}</td></tr>'
bars=''.join(f'<div class="barrow"><span>{role.title()}</span><div class="track"><div style="width:{data["totalTokens"]/tot["totalTokens"]*100:.2f}%"></div></div><b>{data["totalTokens"]/tot["totalTokens"]:.1%}</b></div>' for role,data in usage['roles'].items())
verdicts=''.join(f'<article class="finding"><h3>Finding {i+1}</h3><p>{esc(finding)}</p></article>' for i,finding in enumerate(f for v in usage['verdicts'] for f in v.get('findings',[])))
checks=''
for title,data in [('Original: independent checks',checks0),('Updated: independent checks',checks1)]:
 checks+=f'<details><summary>{title} · {data["passed"]} passed / {data["failed"]} failed</summary><ul>'+''.join(f'<li>{"Pass" if r["pass"] else "FAIL"} — {esc(r["name"])}'+(' · '+esc(r['error']) if not r['pass'] else '')+'</li>' for r in data['checks'])+'</ul></details>'
files=''
for label,key in [('Original','original'),('Updated','reviewed')]:
 m=metrics[key];files+=f'<tr><th>{label}</th><td>{m["productionFiles"]}</td><td>{m["productionLines"]}</td><td>{m["testFiles"]}</td><td>{m["testLines"]}</td></tr>'
reviewed_commit=manifest['reviewedCommit']
page=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tetris 003 · Validator comparison</title><style>
:root{{--paper:#f5f4ee;--ink:#17313a;--muted:#53696d;--line:#d1dcd6;--accent:#066e66;--wash:#e3efe9;--gold:#f6e7be}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,sans-serif}}main{{max-width:1160px;padding:52px 26px 80px;margin:auto}}h1,h2,h3,p{{margin-top:0}}h1{{font-size:clamp(38px,6vw,68px);line-height:1.08;letter-spacing:-.045em;max-width:900px}}h2{{font-size:30px;line-height:1.2}}h3{{font-size:20px}}.eyebrow{{color:var(--accent);font-size:12px;letter-spacing:.15em;text-transform:uppercase;font-weight:800}}.lede{{font-size:20px;max-width:900px;color:var(--muted)}}nav{{display:flex;flex-wrap:wrap;gap:22px;padding:18px 0;border-bottom:1px solid var(--line)}}a{{color:var(--accent);text-underline-offset:3px}}section{{margin-top:50px}}.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}}.card,.panel,details,.finding{{border:1px solid var(--line);border-radius:12px;background:white;padding:22px}}.card strong{{display:block;font-size:31px;line-height:1.2}}.card span,.muted{{color:var(--muted);font-size:14px}}.callout{{background:var(--wash);border-left:4px solid var(--accent);padding:22px;border-radius:0 12px 12px 0}}.caution{{background:var(--gold);border-left-color:#af7914}}.callout p:last-child{{margin-bottom:0}}.table{{overflow:auto;border:1px solid var(--line);border-radius:12px;background:white}}table{{border-collapse:collapse;width:100%;min-width:720px;font-size:14px}}th,td{{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:15px 18px}}thead{{background:var(--wash)}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}.terminal{{background:#102b33;color:#e4f3e9;border-radius:12px;overflow:hidden}}.terminal header{{padding:15px 18px;background:#1c3d45}}pre{{font:13px/1.45 ui-monospace,monospace;overflow:auto;white-space:pre}}.terminal pre{{padding:18px;margin:0;min-height:460px}}code{{font-family:ui-monospace,monospace;font-size:.9em}}pre.command{{background:#17313a;color:white;border-radius:10px;padding:22px}}details{{margin:14px 0}}summary{{cursor:pointer;font-weight:650}}.barrow{{display:grid;grid-template-columns:90px 1fr 55px;gap:14px;align-items:center;margin:15px 0}}.track{{height:16px;background:#e1e8e4;border-radius:6px;overflow:hidden}}.track div{{height:100%;background:var(--accent)}}.finding{{margin:16px 0}}.finding p{{font-size:14px}}footer{{margin-top:45px;border-top:1px solid var(--line);padding-top:20px;color:var(--muted);font-size:13px}}@media(max-width:760px){{.cards,.grid{{grid-template-columns:1fr}}main{{padding:30px 18px}}.terminal pre{{font-size:11px}}}}@media print{{details{{display:block}}body{{font-size:11px}}main{{padding:0}}.cards{{grid-template-columns:repeat(4,1fr)}}a{{color:inherit}}}}
</style></head><body><main>
<p class="eyebrow">Homework 003 · A fresh factory generation · November 20, 2026</p>
<h1>What changed with a broader validator?</h1>
<p class="lede">The updated build separates game rules from scheduling, includes {testcount} executable tests, and keeps its score visible in a 24-row terminal. One cursor-lifecycle correction is directly traceable to validator feedback. Historical token spend for the original run was not retained.</p>
<nav><a href="#quality">Code quality</a><a href="#findings">Validator findings</a><a href="#spend">Tokens &amp; cost</a><a href="#terminal">Terminal checks</a><a href="#method">Method &amp; evidence</a></nav>
<div class="cards"><div class="card"><strong>{testcount} vs 0</strong><span>Included automated tests · updated vs original</span></div><div class="card"><strong>{usage['findingsCount']}</strong><span>Actionable finding recorded in the new run</span></div><div class="card"><strong>{fmt(tot['totalTokens'])}</strong><span>New-run tokens, including cached tokens and retry</span></div><div class="card"><strong>${tot['reportedCostUSD']:.2f}</strong><span>New-run provider-reported cost</span></div></div>
<div class="callout"><p><b>Assessment:</b> the new generation has a cleaner boundary between game rules and the terminal, and leaves repeatable tests behind. It also has fewer optional gameplay features and a less accessible terminal entry point for unit testing. These are observed tradeoffs, not a numerical quality score or proof that the validator caused every difference.</p></div>
<section id="quality"><h2>Code quality, with evidence</h2><div class="table"><table><thead><tr><th>Dimension</th><th>Original · testability + usability</th><th>Updated · four review lenses</th></tr></thead><tbody>
<tr><th>Core independence</th><td><code>TetrisGame</code> imports <code>board.js</code>, which also implements rendering. Its <code>start</code>/<code>stop</code> methods use global timers.</td><td><code>game.js</code> has no imports or host I/O/timer calls. The terminal adapter drives <code>tick()</code> and supplies time. A concrete improvement in dependency separation.</td></tr>
<tr><th>Determinism</th><td>Injectable <code>rng</code>; piece helpers are callable independently of the CLI.</td><td>Injectable <code>random</code>; core actions and board snapshots are callable without terminal setup. Both generations passed deterministic-sequence checks.</td></tr>
<tr><th>Clarity and organization</th><td>Separate modules for board rendering, tetrominoes, game state, and CLI. Explicit SRS kick tables and named scoring/timing constants.</td><td>Three production modules: game, renderer, CLI. Direct domain action methods, but most rule/shape logic is concentrated in one game module. Smaller organization does not itself establish better design.</td></tr>
<tr><th>Boundary testability</th><td>CLI is import-safe and exports <code>handleKey</code>, which can be checked with a fake game.</td><td>CLI initializes at module scope and exports no input handler. Core and renderer are easy to exercise, but CLI behavior currently needs process/PTY checks.</td></tr>
<tr><th>Retained automated tests</th><td>No <code>npm test</code> script or included game tests. Ten external comparison checks passed.</td><td><code>npm test</code> runs {testcount} passing Node tests. Deterministic fixtures cover mechanics and rendering; ten external comparison checks also passed.</td></tr>
<tr><th>Test quality limits</th><td>Prior agent assertions were transient; the new external checks are retained with this report, not installed as the original game's suite.</td><td>Tests run without real terminals, waits, or external services. Some tests group several scenarios and mutate public state directly; CLI cursor cleanup remains outside the included automated suite. Test count is not a coverage metric.</td></tr>
<tr><th>Live display</th><td>A 24-line frame followed by a newline scrolls away its score row in an exactly 24-row terminal.</td><td>TTY rendering omits the trailing newline; score, controls, borders, and board remain visible. Frame-length assertions alone would not establish this.</td></tr>
<tr><th>Gameplay tradeoffs</th><td>Pause/resume, next-piece shape preview, SRS kick tables, 80 ms minimum gravity.</td><td>No pause action; next piece shown as a letter, simple wall kicks, 50 ms minimum gravity, and WASD bindings. These are generation differences; the seed does not require those particular extras.</td></tr>
</tbody></table></div>
<p class="muted">Inspect sources: {source('tetris-003/src/game.js','original game')} · {source('tetris-003/src/index.js','original CLI')} · {source('tetris-003-reviewed/src/game.js','updated game')} · {source('tetris-003-reviewed/src/index.js','updated CLI')} · {source('tetris-003-reviewed/src/renderer.js','updated renderer')} · {source('tetris-003-reviewed/test/game.test.js','mechanics tests')} · {source('tetris-003-reviewed/test/renderer.test.js','renderer tests')}.</p>
<details><summary>Code-size context, not a quality score</summary><div class="table"><table><thead><tr><th>Generation</th><th>Production JS files</th><th>Production lines</th><th>Test files</th><th>Test lines</th></tr></thead><tbody>{files}</tbody></table></div><p>Physical lines include comments and blanks. Counts exclude dependencies, report checks, and generated metadata. See {evidence('code-metrics.json','file-level measurements')}.</p></details></section>
<section id="findings"><h2>What the validator actually changed</h2><p>The updated prompt reviews boundaries, design, local clarity, and test trustworthiness in that order, consolidating overlapping problems into actionable findings. The run recorded <b>{len(usage['verdicts'])} validator verdicts, {usage['rejections']} rejection, and {usage['findingsCount']} finding</b>.</p>
{verdicts}
<div class="callout"><p><b>Observed correction:</b> cursor hiding moved out of <code>render()</code> and into interactive setup. With non-TTY stdin and TTY stdout, the final program prints its frame and exits without hiding the cursor. The doer recorded the correction as a completed subtask under the renderer/input task.</p><p>The original plan contains no recorded validator-origin findings. The new core separation and test task were already planned or implemented before a rejection; they cannot be attributed to this feedback alone.</p></div>
<p>{evidence('usage-summary.json','Verdicts and per-call records')} · {source('tetris-003-reviewed/.factory/plan.md','updated plan and finding subtask')} · {source('tetris-003/.factory/plan.md','original completed plan')} · {evidence('validator-instructions.md','validator prompt snapshot')}.</p></section>
<section id="spend"><h2>Token spend: measured new run, unavailable baseline</h2><div class="callout caution"><p><b>An exact cost comparison is not possible.</b> The original factory used <code>--no-session</code> and discarded usage events. No per-run usage ledger was found. Its token count and dollar spend are <b>unknown, not zero</b>; no cost difference, percentage saving, or value-per-dollar claim can be calculated.</p></div>
<div class="table"><table><thead><tr><th>Metric</th><th>Original</th><th>Updated</th></tr></thead><tbody><tr><th>Tokens, including cache</th><td>Unavailable</td><td>{fmt(tot['totalTokens'])}</td></tr><tr><th>Provider-reported cost</th><td>Unavailable</td><td>${tot['reportedCostUSD']:.6f}</td></tr><tr><th>Recorded machine invocations</th><td>No retained usage ledger</td><td>{tot['callsStarted']} started / {tot['callsFinished']} ended</td></tr><tr><th>Assistant messages with usage</th><td>Unavailable</td><td>{tot['assistantMessages']}; {tot['messagesMissingUsage']} missing usage records</td></tr></tbody></table></div>
<h3 style="margin-top:28px">Where the new run spent tokens</h3>{bars}
<div class="table"><table><thead><tr><th>Machine</th><th>Calls</th><th>Input</th><th>Cache read</th><th>Output</th><th>Total tokens</th><th>Reported USD</th></tr></thead><tbody>{roles}<tr><th>Total</th><td>{tot['callsStarted']}</td><td>{fmt(tot['input'])}</td><td>{fmt(tot['cacheRead'])}</td><td>{fmt(tot['output'])}</td><td>{fmt(tot['totalTokens'])}</td><td>${tot['reportedCostUSD']:.6f}</td></tr></tbody></table></div>
<p>Numbers are pi's emitted usage fields, summed once per assistant <code>message_end</code>. Cache writes: {fmt(tot['cacheWrite'])}. Reported reasoning tokens: {fmt(tot['reasoning'])}; these are not added again to the total. Cached tokens count as tokens but do not cost the same as fresh input. Costs use emitted <code>usage.cost.total</code>, not a reconstruction from public prices; all {tot['providerReportedCostMessages']} usage records identify provider-reported totals. This is telemetry, not a billing invoice.</p>
<p><b>Scope and interruption:</b> these totals cover factory machine calls only. They exclude this assistant's orchestration, code inspection, report generation, and terminal checks. One observer pipe-write failure interrupted the final test task after files were written. The target was resumed, and the totals include both that attempt and the resume. The observer was corrected to use blocking stdout. Wall-clock time was about {usage['elapsedSeconds']/60:.1f} minutes including the interruption; it is not a clean speed benchmark.</p>
<p>{evidence('usage.jsonl','Raw usage ledger')} · {evidence('usage-summary.json','Aggregated usage')} · {evidence('observer-pi.py','Observer source')} · {evidence('summarize-usage.py','Aggregation script')}.</p></section>
<section id="terminal"><h2>Checked in a real 80 × 24 PTY</h2><p>Both commands launched, rendered, and quit with exit code 0 after Q. Canonical input and echo settings were restored. Captures below show the visible terminal after two seconds, reconstructed from its cursor operations; colored backgrounds are represented as blocks. Random piece positions are not a comparison metric.</p>
<div class="grid"><article class="terminal"><header>Original · score row scrolled away</header><pre>{esc(orig['normal'])}</pre></article><article class="terminal"><header>Updated · full display remains visible</header><pre>{esc(new['normal'])}</pre></article></div>
<p>The original P key also showed its pause state; the updated build does not implement pause. Pure-frame checks covered game-over rendering, but these captures are startup/quit smoke checks, not complete human playthroughs.</p>
<p>{evidence('original-terminal.json','Original PTY results')} · {evidence('reviewed-terminal.json','Updated PTY results')} · {evidence('mixed-tty-check.json','Cursor-fix reproduction check')} · {evidence('capture-terminal.py','Capture and screen-reconstruction script')}.</p>
{checks}
<details><summary>Included updated-suite output · {testcount} passing tests</summary><pre>{esc(testlog)}</pre></details>
<p>Comparison checks adapt to each generation's public API; the ten checks per build are selected examples, not identical suites or coverage measurements. One comparison fixture was corrected to use the new I-piece rotation offset; no generated game code was edited during analysis. {evidence('check-original.cjs','Original check source')} · {evidence('check-reviewed.mjs','Updated check source')}.</p></section>
<section id="method"><h2>How to interpret this experiment</h2><ul>
<li>The baseline is the preserved <code>tetris/tetris-003</code> at commit <code>{manifest['baselineCommit'][:12]}</code>. The new target is <code>tetris/tetris-003-reviewed</code>, completed at <code>{reviewed_commit[:12]}</code>. Original target contents were verified unchanged.</li>
<li>Both use the same saved seed and Kimi K3.1 Pro for game implementation. The original plan was initially produced with Kimi K2.7 Code before the model switch; the new plan was produced with K3.1 Pro. Planner/doer instructions and factory code were held fixed during this new run. The updated validator prompt is the intended change.</li>
<li>The planner independently chose four tasks for the new generation versus six for the original, and explicitly included a test task before the first review. Plans, model variation, prompt history, and the observer retry prevent a controlled causal or cost comparison.</li>
<li>Only the factory's machines wrote the generated game. Analysis added report artifacts and independent checks outside the targets. Validator approval is not proof of defect-free software or comprehensive test coverage.</li>
<li>The console trace records machine summaries and tool status, not every tool's full arguments/output. Oversized transport payload fragments from the observer failure are omitted in the sanitized console log. The usage ledger contains metrics and parsed result objects, not login data.</li>
</ul><p>{evidence('manifest.json','Run manifest and SHA-256 hashes')} · {evidence('console-log.txt','Sanitized console log')} · {evidence('planner-instructions.md','Planner snapshot')} · {evidence('doer-instructions.md','Doer snapshot')}.</p>
<h3>Try either result</h3><pre class="command">npm --prefix tetris/tetris-003 start
npm --prefix tetris/tetris-003-reviewed start
npm --prefix tetris/tetris-003-reviewed test</pre><p>Run games in separate terminals and use their displayed controls. Regenerating this exact target resumes its completed plan; a new generation needs a fresh target path.</p></section>
<footer>Standalone local report · no external assets, network requests, or runtime dependencies. Sources, checks, prompts, and telemetry are preserved beside the report. Token savings remain undetermined because the original spend was not retained.</footer>
</main></body></html>'''
